    /*
     * Add to the Transactions
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	Account
     */
    public Account addToTransactions( UUID parentId, Transaction addTo ) {
	    LOGGER.info("handling AssignTransactionsToAccountEvent - " );
	    
	    Account parentEntity = repository.findById(parentId).get();
	    Transaction child = registry.project( Transaction.class, addTo.getTransactionId());
	    
	    parentEntity.getTransactions().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the Transactions
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	Account
     */
	public Account removeFromTransactions( UUID parentId, Transaction removeFrom ) {
	    LOGGER.info("handling RemoveTransactionsFromAccountEvent " );
	
	    Account parentEntity = repository.findById(parentId).get();
	    Transaction child = registry.project( Transaction.class, removeFrom.getTransactionId());
	    
	    parentEntity.getTransactions().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}

